"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3210],{23210:a=>{a.exports=JSON.parse('{"slug":"samolet-tekhdefolt-reyting-gendirektor","locale":"zh","title":"Samolet一个月内延迟还债、遭2次评级下调并更换总经理","description":"Samolet发生技术违约，2家机构降至BBB，总经理在欧盟制裁后离职。分析对购房者与投资者的意义。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年九月末，Samolet集团延迟一天偿还2.5十亿卢布债券，解释为付款划转延误。这称技术违约：企业称有资金，但未按时到账。随后ACRA将其信用等级降为BBB、展望负面；十月15日NKR也从A降至相同等级。"},{"id":"b002","kind":"paragraph","text":"信用等级衡量偿债可能性，像个人信用历史，越差则新借款利息越高。NKR解释为债务负担增加、偿债指标转弱及盈利下降。负面展望关联房贷项目收紧：房贷贵，住房更难卖，开发商更难还债。"},{"id":"b003","kind":"paragraph","text":"十月中欧盟制裁Samolet及总经理安娜\xb7阿金希娜，理由为符拉迪沃斯托克工地使用朝鲜工人，欧盟认为违反2017年联合国制裁。十月16日企业宣布阿金希娜因个人原因离任，拟由“Samolet Select”负责人伊万\xb7伊万诺夫接替。另有2名董事辞职，未公布姓名。"},{"id":"b004","kind":"paragraph","text":"最大债权人Sber在该公司贷款274.2十亿卢布。第一副行长韦佳欣称正与所有债权人合作，制定改善计划。十月9日建设部召集开发商、银行和税务部门，要求银行动员资源确保大型开发商交房；官方通报未点名公司。"},{"id":"b005","kind":"paragraph","text":"问题并非十月才开始。2026年初Samolet请求政府48–50十亿优惠贷款，但财政部小组未认定有严重问题。IPO发行价950卢布，七月放弃分红后跌破300，十月16日约247.6，近乎低4倍。并非个案：Expert RA称2026年前9个月，高评级实体企业评级行动中下调占8.1%，2025全年仅1.8%。"},{"id":"b006","kind":"paragraph","text":"购房者最关心能否完工。建设部要求如此，最大债权人也制订计划，因此当局和银行目前支持交付。债券持有人面临评级下调、风险提高，市场要求更高收益。继续持有是在押注Sber方案，现在卖则锁定低价损失。方案内容及能否赶在下次付款前落地，仍未知。"},{"id":"b007","kind":"heading","text":"Samolet发生了什么？"},{"id":"b008","kind":"paragraph","text":"2026年九月末延迟一天偿还2.5十亿卢布债券。之后ACRA和NKR降至BBB、负面展望，欧盟制裁企业和总经理，阿金希娜宣布离职。"},{"id":"b009","kind":"heading","text":"技术违约是什么？"},{"id":"b010","kind":"paragraph","text":"企业有钱但款项未按时到账，导致债务支付迟几天。Samolet延迟一天，称划转问题；市场仍视为现金紧张信号。"},{"id":"b011","kind":"heading","text":"Samolet住房会怎样？"},{"id":"b012","kind":"paragraph","text":"十月9日建设部要求银行动员资源，确保开发商完工并履行购房者义务。最大债权人Sber正在制订改善方案，具体内容未公布。"}],"sources":[{"label":"俄罗斯债市十月12日至16日发生多少违约","url":"https://frankmedia.ru/310263"},{"label":"Samolet宣布更换总经理","url":"https://frankmedia.ru/310548"},{"label":"NKR继ACRA之后将Samolet降至BBB","url":"https://frankmedia.ru/310395"},{"label":"受制裁的俄罗斯开发商宣布更换负责人","url":"https://lenta.ru/news/2026/10/16/popavvshiy-pod-sanktsii-rossiyskiy-zastroyschik-ob-yavil-o-smene-gendirektora"},{"label":"当局要求俄罗斯银行动员支持开发商","url":"https://lenta.ru/news/2026/10/09/mobilizovat"}],"sourceBodySha256":"556c692bc853437d88a15a7dc68acf4d7948a9d61dd5f274aba150be3640471e"}')}}]);